{
  "action": "split_state",
  "target": "S_DATA 分支中 bit_cnt==DATA_W-1 的跳转目标",
  "params": {
    "from_state": "S_DATA",
    "wrong_next_state": "S_IDLE",
    "correct_next_state": "S_STOP",
    "condition": "baud_tick && (bit_cnt == DATA_W-1)",
    "txd_at_transition": "1'b1"
  },
  "rationale": "数据位最后一拍必须进入 STOP 状态输出停止位，而不是直接跳回 IDLE，否则破坏 A4 的 DATA→STOP 合法跳转并导致帧缺停止位。"
}
